  // Lucide glyphs (paths copied from lucide-react, the icon names the hub screens use).
  const I=(n,c='')=>ICON[n]?`<svg class="ico ${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[n]}</svg>`:'';
  const glyph=n=>`<span class="glyph">${I(n)}</span>`;
  const USER='Sari Wulandari';
  // The mark each answer wears, as in the hub: lib/builds.ts, supplies/book-data.ts, maintenance/format.ts, contracts/groups.ts, vendors/kinds.ts, locations/places-data.ts, letters.tsx, original-sheets.tsx.
  const buildIcon={LAND:'Map',BUILDING:'Building',TECH:'Cpu',VEHICLE:'Car',FFE:'Armchair',IT:'Monitor',AUDIO:'Speaker',OE:'Box',SOFTWARE:'AppWindow',DEFERRED:'Clock',CIP:'Hammer'};
