  const supplierKinds=[['Utilities','Zap'],['Cleaning','Sparkles'],['Workshop','Wrench'],['AC','Snowflake'],['Logistics','Truck'],['Office','Printer'],['Landlord','Building'],['Other','Briefcase']];
  const kindIcon=k=>(supplierKinds.find(([x])=>x===k)||supplierKinds.at(-1))[1];
  const paperTypes=[['BPKB','ScrollText'],['STNK','CarFront'],['Land certificate','Landmark'],['Warranty','BadgeCheck'],['Signed agreement','FileText'],['Permit','Stamp'],['Invoice','Receipt'],['Service report','ClipboardCheck'],['Photo','Image'],['Manual','BookOpen'],['Other','FilePlus2']];
  const paperIcon=t=>(paperTypes.find(([x])=>x===t)||paperTypes.at(-1))[1];
  const unitIcon={DAYS:'CalendarDays',MONTHS:'Calendar',KM:'Gauge'};
  const results=[['Good','Good','CircleCheck'],['Needs attention','Needs attention','TriangleAlert'],['Broken','Broken','CircleX']];
