  const letterGroups=[['goods','Goods & documents','Package'],['people','People','Users'],['notices','Notices & requests','Megaphone'],['system','By system','Cpu']];
  const actionIcon={attach:'Paperclip',contract:'Plus','cover-existing':'Link',task:'CalendarPlus',inspection:'ClipboardCheck',repair:'Wrench',letter:'PencilLine',move:'ArrowLeftRight',claim:'ShieldAlert',bill:'ReceiptText',meter:'Gauge',coverage:'ListChecks','complete-task':'CircleCheck',original:'Archive','document-subject':'Link','letter-reference':'Link',supply:'Package',asset:'Plus',milestone:'Flag','project-progress':'Activity',projectresult:'PackagePlus',operating:'Fuel',allocate:'UserRound',utilitycycle:'CalendarPlus',receivable:'Receipt',followup:'AlarmClock','utility-reading':'Gauge',edit:'Pencil',replace:'Repeat','finance-project':'Landmark','repair-contract':'Link',receive:'PackageCheck',projectwork:'Hammer',handover:'Handshake','return-original':'Undo2'};
  const phone=()=>state.phone||window.innerWidth<768;
  const days=on=>on?Math.round((Date.parse(on+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000):null;
  const addDays=(on,n)=>{const d=new Date(on+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
  const num=n=>Number(n||0).toLocaleString('id-ID');
  const compact=n=>{n=Number(n||0);if(!n)return 'Rp 0';if(n>=1e9)return 'Rp '+(n/1e9).toLocaleString('id-ID',{maximumFractionDigits:1})+' bn';if(n>=1e6)return 'Rp '+(n/1e6).toLocaleString('id-ID',{maximumFractionDigits:n>=1e8?0:1})+' M';if(n>=1e3)return 'Rp '+Math.round(n/1e3)+' K';return 'Rp '+n;};
