  function finishCommit(f,type,v,r,newRecord,message){if(r&&f.before!==undefined&&r.status!==f.before)stamp(r,r.status);state.stack.pop();const stay=type==='receive'||type==='bill'&&['supply','repair'].includes(r?.type);if(newRecord&&!stay)state.stack.push({kind:'record',id:newRecord.id});ext?.afterCommit(f,type,v,r,newRecord);state.message=message;render();persist();}
  function guideBody(){
    const descriptions={overview:'Due documents, open repairs and requests → open the source record.',supply:'Site → request → approval → supplier order → receipt → Finance draft bill.',repair:'Site + optional asset → maintenance agreement / inspection → work → bills and claim.',task:'Asset or site → interval → completion / inspection → optional repair → next due.',asset:'Identity + site / holder → documents, originals, agreements, service and lifecycle.',contract:'Type + counterparty + site scope → covered assets → evidence, bills and renewals.',site:'Facility facts → assets, agreements, repairs, service, requests and documents.',supplier:'Supplier identity → agreements, repairs, service tasks, invoices and evidence.',letter:'Choose a letter form → draft → references → issue. References do not perform the work.',document:'Metadata / scan → one or more subjects → physical original → custody events.'};
    const connections=[
      ['Asset ↔ site / holder','Register asset selects its initial site and holder. Later use Move; one movement record updates the current asset location.'],
      ['Asset ↔ repair ↔ service','Record repair on the asset, or select the asset in Repairs. Schedule service selects an asset or site. Record done creates history, advances next due and can create a repair from findings.'],
      ['Agreement ↔ covered assets','Add contract chooses group, type, scope and compatible assets. Manage coverage changes the same roster. Existing on an asset adds that asset to an existing agreement.'],
      ['Insurance ↔ repair ↔ claim','Record claim starts from a policy or repair. Choose insured object, incident and optional repair; attach evidence. Claim and repair have different costs and statuses.'],
      ['Document ↔ many records','Paper (Attach) selects one already filed or files a new one. References adds / removes subjects. Both entry points read the same document.'],
      ['Document ↔ original ↔ custodian','Kept in storage creates a separately tracked original. Hand over / Take back records who holds it now, its place and history; optionally creates a draft letter.'],
      ['Work ↔ Finance bill','Send bill to Finance on a repair, agreement or received supply creates a draft with that source reference. Posted costs are read from Finance.'],
      ['Asset ↔ replacement / disposal','Propose replacement preserves the old asset and selects a separately registered new asset at installation. Request disposal awaits Finance review.'],
      ['Letter ↔ items and supporting records','Goods out, goods in, handover and collection authority can list existing assets, physical originals, document copies or other items typed freely. Each line keeps its reference and paper wording. Related work is separate context. Issuing does not move the asset or original.']
    ];
    return (ext?.guide()||'')+section('How connections are recorded',connections.map(([name,text])=>`<div class="coverage-row"><span><strong>${E(name)}</strong><span class="sub">${E(text)}</span></span></div>`).join(''))+section('All GA menus',`<div class="coverage-group">${menus.map(([name,type])=>`<div class="coverage-row"><span><strong>${name}</strong><span class="sub">${E(descriptions[type])}</span></span>${B('Open menu','menu',type)}</div>`).join('')}</div>`)+section('All 11 asset forms',`<div class="coverage-group">${seed.builds.map(b=>`<div class="coverage-row">${nameCell(buildIcon[b.code],b.label,`${b.classes.length} ${b.classes.length===1?'class':'classes'} · ${b.fields.length} specification fields`)}${B('Open example','open',all('asset').find(a=>a.build===b.code).id)}</div>`).join('')}</div>`)+section('All 17 agreement types',`<div class="coverage-group">${seed.contractTypes.map(t=>`<div class="coverage-row">${nameCell(groupIcon[t.group],t.label,t.group)}${B('Open example','open',all('contract').find(c=>c.contractType===t.code).id)}</div>`).join('')}</div>`)+section('Additional connected sheets',`<p>Inspections, service completion, insurance claims, document originals, custody, asset movement, replacements, disposal requests, utility readings and Finance bill previews.</p>`)+section('Prototype scope',`<p>All data is fictional and resets when the page reloads. Forms and workflow steps are simulated. Finance posting, payment, real uploads and production APIs are outside this prototype.</p>`);
  }
  function persist(){window.openai?.setWidgetState?.({modelContent:{menu:state.menu,record:state.stack.filter(e=>e.kind==='record').at(-1)?.id||null},privateContent:{version:3,menu:state.menu,kind:state.kind,group:state.group,phone:state.phone}})?.catch(()=>{});}
  function requestBack(){const top=current();if(top?.kind==='form'&&top.dirty){root.querySelector('.discard-dialog').showModal();return;}state.stack.pop();state.message='';render();persist();}
  root.addEventListener('click',e=>{if(state.colsOpen&&!e.target.closest('.cols-wrap')){state.colsOpen=false;if(!e.target.closest('[data-action]')){renderPage();return;}}const button=e.target.closest('[data-action]');if(!button)return;const {action,value,context}=button.dataset;
    if(ext?.action(action,value,context))return;
    if(action==='keep-editing'){root.querySelector('.discard-dialog').close();return;}if(action==='discard'){root.querySelector('.discard-dialog').close();state.stack.pop();render();return;}
    if(action==='letter-item-add'||action==='letter-item-remove'){const f=current();if(f?.kind!=='form')return;readValues(f);f.values.lineItems??=[];if(action==='letter-item-add')f.values.lineItems.push({source:'other',ref:'',name:'',quantity:'1',unit:'pcs',note:''});else f.values.lineItems.splice(Number(value),1);f.dirty=true;renderLayer();return;}
    if(action==='back'){requestBack();return;}
    if(action==='device'){state.phone=!state.phone;render();persist();return;}
    if(action==='open'){open(value);return;}
    if(action==='form'){form(value,context||'',value==='edit'?context:'');return;}
    if(action==='guide'){state.stack.push({kind:'guide'});renderLayer();return;}
    if(action==='scenario'){state.menu=value==='policy'?'contract':'asset';state.stack=[];state.message='';render();open(value);return;}
    if(action==='menu'){state.menu=value;state.stack=[];state.kind='All kinds';state.group='All groups';state.status='All statuses';state.search='';state.message='';Object.assign(state,{tab:'',kpi:'',chips:{},site:'',colsOpen:false});render();persist();window.scrollTo(0,0);return;}
    if(action==='chip'){setChip(button.dataset.group,value);render();return;}
    if(action==='kpi'){state.kpi=state.kpi===value?'':value;if(state.kpi&&button.dataset.tab)state.tab=button.dataset.tab;render();return;}
    if(action==='tab'){state.tab=value;state.kpi='';state.chips={};state.colsOpen=false;renderPage();return;}
    if(action==='columns'){state.colsOpen=!state.colsOpen;renderPage();return;}
    if(action==='scroll'){const el=document.getElementById(value);el?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return;}
    if(action==='filters'){state.stack.push({kind:'filters'});renderLayer();return;}
    if(action==='pick'){state.site=value;render();return;}
    if(action==='transition'){const [id,next]=value.split('|'),r=get(id);const permitted={repair:{Approved:'In progress',Completed:'Closed'},supply:{Requested:['Approved','Rejected']},letter:{Draft:'Issued'},claim:{Draft:'Submitted',Submitted:'Under review'},replacement:{Proposed:'Approved',Approved:'Purchased',Installed:'Closed'}};const allowed=permitted[r?.type]?.[r?.status];if(!(Array.isArray(allowed)?allowed.includes(next):allowed===next))return;r.status=next;log(r,'Status changed to '+next);stamp(r,next);state.message='Status updated.';render();persist();}
  });
  root.addEventListener('change',e=>{const t=e.target;if(t.dataset.filter){state[t.dataset.filter]=t.value;renderPage();return;}if(t.dataset.col){const k=hideKey(),h=new Set(state.hide[k]||[]);t.checked?h.delete(t.dataset.col):h.add(t.dataset.col);state.hide[k]=[...h];renderPage();return;}if(t.matches('[data-dock-tab]')){state.tab=t.value;state.kpi='';state.chips={};renderPage();return;}if(t.matches('[data-more]')){if(t.value)form(t.value,t.dataset.more);return;}const f=current();if(f?.kind!=='form')return;readValues(f);f.dirty=true;if(ext?.change(t,f))return;
    if(t.name?.startsWith('line.')){const [,index,key]=t.name.split('.'),i=f.values.lineItems[Number(index)];if(key==='source'){i.ref='';i.name='';i.quantity='1';i.unit=i.source==='asset'?'unit':i.source==='original'?'original':i.source==='document'?'copy':'pcs';}if(key==='ref'){i.name=title(i.ref);i.quantity='1';}if(['source','ref'].includes(key)){renderLayer();return;}}
    if(t.matches('[data-reactive]')||t.type==='checkbox'&&['withOriginal','makeRepair'].includes(t.name)){if(t.name==='build'){f.values.className=build(f.values.build).classes[0];f.values.specs={};}if(t.name==='asset'){f.values.site=get(f.values.asset)?.site||f.values.site;f.values.contract='';}if(t.name==='site'&&f.form==='repair'){f.values.asset='';f.values.contract='';}if(t.name==='cgroup'){const first=seed.contractTypes.find(x=>x.group===f.values.cgroup);f.values.contractType=first.code;f.values.assets=(f.values.assets||[]).filter(id=>eligibleAssets(first).some(a=>a.id===id));f.values.scope='SITE';}if(t.name==='contractType'){f.values.assets=(f.values.assets||[]).filter(id=>eligibleAssets(ct(f.values.contractType)).some(a=>a.id===id));f.values.scope='SITE';}if(t.name==='policy'){const p=get(f.values.policy);f.values.asset=p?.assets?.[0]||'';f.values.site=p?.site;f.values.repair='';}if(t.name==='target'&&f.values.target==='SITE'){f.values.asset='';f.values.unit='MONTHS';}renderLayer();}
  });
  root.addEventListener('input',e=>{if(e.target.matches('[data-search]')){state.search=e.target.value;const pos=e.target.selectionStart;renderPage();const input=work.querySelector('[data-search]');input.focus();input.setSelectionRange(pos,pos);return;}if(current()?.kind==='form')current().dirty=true;});
  root.addEventListener('submit',e=>{if(e.target.id==='ga-active-form'){e.preventDefault();commit();}});
  window.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('[data-action="open"][tabindex]')){e.preventDefault();open(e.target.dataset.value);return;}if(e.key==='Escape'&&state.stack.length&&!root.querySelector('.discard-dialog').open){e.preventDefault();requestBack();}});
  let wasPhone=null;window.addEventListener('resize',()=>{if(phone()!==wasPhone){wasPhone=phone();render();}});
  root.querySelector('.discard-dialog').addEventListener('cancel',e=>{e.preventDefault();root.querySelector('.discard-dialog').close();});
